// @ts-strict
"use strict";
// Reference tables (header buttons "Tavola periodica" and "Addotti"): periodic table with isotopes, ESI adducts, isotope pattern
// of a formula (computed here), common neutral losses.
// Data of the elements: elements.js (generated by tools/genera_elementi.py). Classic script, after explore.js.
(() => {
  const Qs = s => document.querySelector(s), H = EH;
  const ELECTRON = 0.00054858;
  const EL = Object.fromEntries(ELEMENTS.map(e => [e.s, e]));
  // monoisotopic mass of an element = exact mass of its most abundant isotope
  const mono = s => { const e = EL[s]; if (!e || !e.iso.length) return null; return e.iso.reduce((a, b) => (b[2] > a[2] ? b : a))[1]; };
  function massOf(f) {                                     // simple formulas, e.g. "CH3COO", "C2H3N"
    let m = 0;
    for (const [, s, n] of f.matchAll(/([A-Z][a-z]?)(\d*)/g)) { const v = mono(s); if (v == null) throw new Error(s); m += v * (n ? +n : 1); }
    return m;
  }
  const sub = f => H(f).replace(/(\d+)/g, "<sub>$1</sub>");

  // periodic table: markup, layout and behaviour live in tavola-periodica.js (shared with the Teoria)
  const { periodic, bindPeriodic } = TAVOLA.create({ elements: ELEMENTS, t: (k, p) => I18N.t(k, p), nome: e => I18N.t(`el.${e.s}`) });


  // ---------------------------------------------------------------- adducts
  // k: how many molecules M; add/sub: what is added or removed; z: charge
  const ADD = [
    { n: "[M+H]+", k: 1, add: "H", z: 1, exp: 1, note: "tbl.add.note.mh" },
    { n: "[M+NH4]+", k: 1, add: "NH4", z: 1, exp: 1, note: "tbl.add.note.mnh4" },
    { n: "[M+Na]+", k: 1, add: "Na", z: 1, exp: 1, note: "tbl.add.note.mna" },
    { n: "[M+K]+", k: 1, add: "K", z: 1, exp: 1, note: "tbl.add.note.mk" },
    { n: "[M+H-H2O]+", k: 1, add: "H", sub: "H2O", z: 1, note: "tbl.add.note.mhh2o" },
    { n: "[M+CH3OH+H]+", k: 1, add: "CH5O", z: 1, note: "tbl.add.note.mch3oh" },
    { n: "[M+H+ACN]+", k: 1, add: "C2H4N", z: 1, note: "tbl.add.note.mhacn" },
    { n: "[M+2H]2+", k: 1, add: "H2", z: 2, note: "tbl.add.note.m2h" },
    { n: "[2M+H]+", k: 2, add: "H", z: 1, note: "tbl.add.note.2mh" },
    { n: "[2M+Na]+", k: 2, add: "Na", z: 1, note: "tbl.add.note.2mna" },
    { n: "[M]+", k: 1, add: "", z: 1, note: "tbl.add.note.mcat" },
    { n: "[M]-", k: 1, add: "", z: -1, note: "tbl.add.note.man" },
    { n: "[M-H]-", k: 1, sub: "H", z: -1, exp: 1, note: "tbl.add.note.mminush" },
    { n: "[M+HCOO]-", k: 1, add: "CHO2", z: -1, exp: 1, note: "tbl.add.note.mhcoo" },
    { n: "[M+Cl]-", k: 1, add: "Cl", z: -1, exp: 1, note: "tbl.add.note.mcl" },
    { n: "[M+CH3COO]-", k: 1, add: "C2H3O2", z: -1, note: "tbl.add.note.mch3coo" },
    { n: "[M-H-H2O]-", k: 1, sub: "H3O", z: -1, note: "tbl.add.note.mmhh2o" },
    { n: "[M+Na-2H]-", k: 1, add: "Na", sub: "H2", z: -1, note: "tbl.add.note.mna2h" },
    { n: "[M-2H]2-", k: 1, sub: "H2", z: -2, note: "tbl.add.note.mm2h" },
    { n: "[2M-H]-", k: 2, sub: "H", z: -1, note: "tbl.add.note.2mminush" },
  ];
  ADD.forEach(a => { a.shift = (a.add ? massOf(a.add) : 0) - (a.sub ? massOf(a.sub) : 0) - a.z * ELECTRON; });
  // for the tests: the shifts are compared with the Python lists
  window.QADD = ADD;
  const mzOf = (a, M) => (a.k * M + a.shift) / Math.abs(a.z);
  const fmtAd = n => H(n).replace(/([A-Z][a-z]?|\))(\d+)/g, "$1<sub>$2</sub>").replace(/(\d?[+-])$/, "<sup>$1</sup>");
  const sgn = x => (x >= 0 ? "+" : "&minus;");
  // The world of the loaded files picks the view of the Adducts and Neutral losses panels: unit resolution (LR) = rounded to the unit, few columns;
  // high resolution (an Orbitrap / Q-TOF file is loaded) = four decimals and more details. No file open = the detailed view.
  const hrOn = () => {
    if (!(window.HR && typeof E !== "undefined")) return true;
    const fs = E.files.filter(f => !f.gone);
    return !fs.length || fs.some(f => HR.isHr(f, 1) || HR.isHr(f, 2));
  };
  // the search box (ricerca.js) reads the world of the files from here
  window.QHR_ON = hrOn;
  const NL_CHEV = '<svg class="nlch" width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 6l3 3 3-3"/></svg>';
  // the less common adducts stay folded until the student opens them (one fold for the shown polarity)
  const AD = { pol: 1, more: false, open: new Set() };
  const adPolStart = () => { AD.pol = typeof E !== "undefined" && E.files.some(f => f.polarity === "negative") && !E.files.some(f => f.polarity === "positive") ? -1 : 1; };

  // Differences between adducts, to recognise pairs of peaks of the same compound. Only the essential pairs: references, never labels on the user's spectrum
  function calcAdductDiffs() {
    const shift = n => { const a = ADD.find(x => x.n === n); return a ? a.shift : 0; };
    return [
      { p: 1, pair: "Na &minus; H", d: shift("[M+Na]+") - shift("[M+H]+") },
      { p: 1, pair: "NH<sub>4</sub> &minus; H", d: shift("[M+NH4]+") - shift("[M+H]+") },
      { p: 1, pair: "K &minus; H", d: shift("[M+K]+") - shift("[M+H]+") },
      { p: 1, pair: "ACN", d: shift("[M+H+ACN]+") - shift("[M+H]+") },
      { p: -1, pair: "HCOO", d: shift("[M+HCOO]-") - shift("[M-H]-") },
      { p: -1, pair: "Cl", d: shift("[M+Cl]-") - shift("[M-H]-") },
    ];
  }
  window.QADD_DIFFS = calcAdductDiffs();

  // The one source of the displayed values: shifts and m/z rounded to the unit in LR, four decimals in HR. M = neutral mass typed by the student (or null).
  const fmtSh = x => sgn(x) + Math.abs(x).toFixed(4);
  const fmtShLr = x => { const r = Math.round(x); return r === 0 ? "0" : sgn(r) + Math.abs(r); };
  function adductView(hr, M) {
    return ADD.map(a => {
      const div = Math.abs(a.z) > 1 ? " &divide;" + Math.abs(a.z) : "";
      return { n: a.n, pol: Math.sign(a.z), common: !!a.exp, note: a.note,
        shift: (a.k > 1 ? a.k + "M " : "") + (hr ? fmtSh(a.shift) : fmtShLr(a.shift)) + div,
        mz: M == null ? "" : hr ? mzOf(a, M).toFixed(4) : String(Math.round(mzOf(a, M))) };
    });
  }
  window.QADD_VIEW = adductView;
  function diffsHtml() {
    const rows = calcAdductDiffs().map(d => `<tr><th scope="row" class="num">${fmtSh(d.d)}</th><td>${d.pair}</td><td class="muted">${d.p > 0 ? "ESI+" : "ESI&minus;"}</td></tr>`).join("");
    return `<details class="ad-diffs"><summary>${I18N.t("tbl.diff.title")}</summary>
      <div class="muted sm">${I18N.t("tbl.diff.intro")}</div>
      <table class="adt"><tbody>${rows}</tbody></table></details>`;
  }

  // One list for the shown polarity: a row per adduct (name | shift | m/z of the typed mass), the row is the button that opens its one-line note
  function adducts(M) {
    const hr = hrOn(), l = adductView(hr, M).filter(a => a.pol === AD.pol);
    const row = a => {
      const open = AD.open.has(a.n);
      return `<div class="ar${a.common ? " exp" : ""}" data-n="${H(a.n)}"><button type="button" class="arow" aria-expanded="${open}" aria-controls="adn-${ADD.findIndex(x => x.n === a.n)}"><span class="arn">${fmtAd(a.n)}</span><span class="ars">${a.shift}</span>${a.mz ? `<span class="arm"><i>m/z</i> ${a.mz}</span>` : ""}${NL_CHEV}</button><div class="adnote" id="adn-${ADD.findIndex(x => x.n === a.n)}"${open ? "" : " hidden"}>${I18N.t(a.note)}</div></div>`;
    };
    return l.filter(a => a.common).map(row).join("")
      + `<div class="admore"><button type="button" class="adtog" aria-expanded="${AD.more}">${I18N.t("tbl.add.more")}</button></div>`
      + (AD.more ? l.filter(a => !a.common).map(row).join("") : "")
      + (hr ? diffsHtml() : "");
  }
  function adductTab() {
    adPolStart();
    return `<div class="adbar"><div class="sb-search-box"><svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="6.5" cy="6.5" r="4.5"/><path d="M10 10l4 4"/></svg><input id="ad-in" placeholder="${I18N.t("tbl.add.placeholder")}" autocomplete="off"></div>
      <span class="seg" id="ad-pol"><button type="button" data-p="1" class="${AD.pol > 0 ? "on" : ""}">ESI+</button><button type="button" data-p="-1" class="${AD.pol < 0 ? "on" : ""}">ESI&minus;</button></span></div>
      <div id="ad-msg" class="muted sm"></div><div class="nlhint muted" id="ad-hint">ⓘ ${I18N.t("tbl.add.hint")}</div>
      <div id="ad-tbl">${adducts(null)}</div>`;
  }
  function bindAdducts(root) {
    const inp = root.querySelector("#ad-in"), msg = root.querySelector("#ad-msg"), tb = root.querySelector("#ad-tbl");
    // the list is rebuilt at every keystroke: the open / folded state lives in AD
    let lastM = null;
    const redo = () => { tb.innerHTML = adducts(lastM); };
    tb.onclick = e => {
      const t = e.target.closest(".adtog");
      if (t) { e.preventDefault(); AD.more = !AD.more; redo(); const nt = tb.querySelector(".adtog"); if (nt) nt.focus(); return; }
      const b = e.target.closest(".arow"); if (!b) return;
      const n = b.closest(".ar").dataset.n, d = b.nextElementSibling;
      if (AD.open.has(n)) AD.open.delete(n); else AD.open.add(n);
      d.hidden = !AD.open.has(n); b.setAttribute("aria-expanded", String(AD.open.has(n)));
    };
    root.querySelectorAll("#ad-pol button").forEach(b => b.onclick = () => {
      AD.pol = +b.dataset.p; root.querySelectorAll("#ad-pol button").forEach(x => x.classList.toggle("on", x === b)); redo();
    });
    inp.oninput = async () => {
      const t = inp.value.trim().replace(",", ".");
      if (!t) { msg.textContent = ""; lastM = null; redo(); return; }
      if (/^\d+(\.\d*)?$/.test(t)) { msg.textContent = ""; lastM = +t; redo(); return; }
      try { const r = await (await fetch("api/formula?f=" + encodeURIComponent(t))).json(); if (r.error) throw new Error(r.error);
        let M = r.neutral; try { M = massOf(r.formula); } catch (_) { /* element without isotope data here: use the server value */ }
        msg.innerHTML = `${sub(r.formula)}: M = ${hrOn() ? M.toFixed(4) : Math.round(M)}`; lastM = M; redo(); }
      catch (e) { msg.textContent = I18N.t("tbl.add.invalid"); lastM = null; redo(); }
    };
  }

  // ---------------------------------------------------------------- common neutral losses (MS/MS and in-source)
  // The masses are computed from the formulas (exact mass rounded to the integer); the "typical of" column summarises what the reviews below
  // describe for even-electron ions in ESI-MS/MS. A loss is only a hypothesis: it must be checked against the structure.
  // «Perdite neutre»: one compact line per loss (Δm | formula | short label); the line itself is the button that opens loss name, full description,
  // exact mass, mechanism and source. Losses with the same nominal mass share ONE line (formulas side by side). Radicals carry a small dot with a tooltip.
  // «Cerca Δm» lists single, pair and repeated candidates.
  // state kept while the window is open (the ruler of the spectrum can fill q)
  const NL = { q: "", pols: new Set(["+", "-"]), open: new Set() };
  const fl = f => sub(f.replace(/^(CH3|NO2|Cl)$/, "•$1")).replace(/^•/, "•");   // radicals are written with the dot
  const NL_TOL = () => hrOn() ? 0.003 : 0.5, NL_DEC = () => hrOn() ? 4 : 0;
  const lossDet = l => {
    const m = massOf(l.f);
    // unit resolution: no exact mass (it would need mass accuracy); HR adds it with four decimals
    const det = hrOn() ? I18N.t("tbl.loss.detail", { m: m.toFixed(4), mech: H(I18N.t(l.mech)) }) : I18N.t("tbl.loss.detailLr", { mech: H(I18N.t(l.mech)) });
    return `<div class="nld-it" data-l="${l.f}"><div class="nld-name"><b>${fl(l.f)}</b> ${H(I18N.t(l.name))}</div><div>${H(I18N.t(l.seen))}</div>${l.rad ? `<div class="nlrad-t">• ${H(I18N.t(LOSS_RAD))}</div>` : ""}<div>${det}</div></div>`;
  };
  // one line: id keys the open state, ls = the losses (one, or several with the same nominal mass)
  const lossRow = (ls, o) => {
    const id = ls.length > 1 ? "g" + Math.round(massOf(ls[0].f)) : ls[0].f, open = NL.open.has(id), m = massOf(ls[0].f), rad = ls.some(l => l.rad);
    const hit = ls.some(l => o.hit.has(l.f)), exact = hrOn() ? `<small class="muted" title="${I18N.t("tbl.loss.exactTitle")}">${m.toFixed(4)}</small>` : "";
    const label = ls.length > 1 ? `${I18N.t("tbl.loss.sameShort")}${Math.round(m) === 80 ? " · " + I18N.t("tbl.loss.checkM2") : ""}` : H(I18N.t(ls[0].short));
    return `<div class="nlr${hit ? " hit" : ""}" data-f="${id}"><button type="button" class="nlrow" data-d="${id}" aria-expanded="${open}" aria-controls="nld-${id}"><span class="nlm">${Math.round(m)}${exact}</span><span class="nlf">${ls.map(l => `<b>${fl(l.f)}</b>`).join('<span class="nlsep"> · </span>')}</span><span class="nls">${label}</span>${rad ? `<span class="nlrd" role="img" aria-label="${H(I18N.t("loss.radShort"))}" title="${H(I18N.t("loss.radShort"))}"></span>` : ""}${NL_CHEV}</button>
      <div class="nldet" id="nld-${id}"${open ? "" : " hidden"}>${ls.map(lossDet).join("")}</div></div>`;
  };
  function lossList() {
    const hit = new Set(), q = numIt(NL.q);
    const vis = LOSSES.filter(l => l.pol === "±" || NL.pols.has(l.pol)).sort((a, b) => massOf(a.f) - massOf(b.f));
    if (isFinite(q)) vis.forEach(l => { if (Math.abs(massOf(l.f) - q) <= NL_TOL()) hit.add(l.f); });
    const groups = []; vis.forEach(l => { const n = Math.round(massOf(l.f)), g = groups[groups.length - 1]; if (g && g.n === n) g.ls.push(l); else groups.push({ n, ls: [l] }); });
    return groups.map(g => lossRow(g.ls, { hit })).join("");
  }
  function lossCombosHtml() {
    const q = numIt(NL.q); if (!isFinite(q) || q <= 0) return "";
    const c = lossCombos(q, massOf, NL_TOL()), nm = l => `<b>${fl(l.f)}</b>`, nd = NL_DEC();
    const li = [...c.single.map(x => `<li>${nm(x[0])} <span class="muted">(${massOf(x[0].f).toFixed(nd)})</span></li>`), ...c.pairs.map(p => `<li>${nm(p[0])} + ${nm(p[1])} <span class="muted">(${(massOf(p[0].f) + massOf(p[1].f)).toFixed(nd)})</span></li>`), ...c.reps.map(r => `<li>${r.n} &times; ${nm(r.l)} <span class="muted">(${(r.n * massOf(r.l.f)).toFixed(nd)})</span></li>`)];
    return `<div class="nlc"><b>${I18N.t("tbl.loss.possible")}</b>${li.length ? `<ul>${li.join("")}</ul>` : `<div class="muted sm">${I18N.t("tbl.loss.none", { tol: hrOn() ? "0.003" : "0.5" })}</div>`}</div>`;
  }
  function lossTab() {
    return `<div class="nlbar"><div class="sb-search-box"><svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="6.5" cy="6.5" r="4.5"/><path d="M10 10l4 4"/></svg><input id="nl-q" inputmode="decimal" autocomplete="off" placeholder="${I18N.t("tbl.loss.searchPh")}" value="${H(NL.q)}" title="${I18N.t("tbl.loss.searchTitle")}"></div>
      <span class="seg" id="nl-pol" title="${I18N.t("tbl.loss.polTitle")}"><button type="button" data-p="+" class="${NL.pols.has("+") ? "on" : ""}">ESI+</button><button type="button" data-p="-" class="${NL.pols.has("-") ? "on" : ""}">ESI&minus;</button></span></div>
      <div class="nlhint muted" id="nl-hint">ⓘ ${I18N.t("tbl.loss.hint")}</div><div id="nl-res">${lossCombosHtml()}</div><div id="nl-list">${lossList()}</div>`;
  }
  function bindLoss(root, show) {
    const list = () => { root.querySelector("#nl-list").innerHTML = lossList(); wire(); root.querySelector("#nl-res").innerHTML = lossCombosHtml(); };
    const wire = () => {
      root.querySelectorAll(".nlrow").forEach(b => b.onclick = () => { const id = b.dataset.d, d = b.closest(".nlr").querySelector(".nldet"); if (NL.open.has(id)) NL.open.delete(id); else NL.open.add(id); d.hidden = !NL.open.has(id); b.setAttribute("aria-expanded", NL.open.has(id)); });
      root.querySelectorAll("[data-go]").forEach(a => a.onclick = e => { e.preventDefault(); show(a.dataset.go); });
    };
    wire();
    root.querySelector("#nl-q").oninput = e => { NL.q = e.target.value; list(); };
    root.querySelectorAll("#nl-pol button").forEach(b => b.onclick = () => {
      const p = b.dataset.p;
      if (NL.pols.has(p)) {
        if (NL.pols.size === 1) NL.pols.add(p === "+" ? "-" : "+");
        NL.pols.delete(p);
      } else {
        NL.pols.add(p);
      }
      root.querySelectorAll("#nl-pol button").forEach(x => x.classList.toggle("on", NL.pols.has(x.dataset.p)));
      list();
    });
  }
  // the polarity of the loaded files sets the filter when the window opens (the student can change it)
  function lossPolStart() {
    try { const fl = typeof shown === "function" && shown().length ? shown() : E.files.filter(f => f.vis), pos = fl.some(f => f.polarity === "positive"), neg = fl.some(f => f.polarity === "negative"); NL.pols = pos && !neg ? new Set(["+"]) : neg && !pos ? new Set(["-"]) : new Set(["+", "-"]); } catch (_) { NL.pols = new Set(["+", "-"]); }
  }

  // ---------------------------------------------------------------- isotope pattern, computed here (no external library)
  // Unit resolution: isotopologues are grouped by nominal mass offset (M, M+1, M+2...); in each group we keep the total
  // probability and the probability-weighted exact mass. Elements are combined by convolution (n atoms: by squaring).
  const counts = f => { const n = {}; for (const [, s, k] of f.matchAll(/([A-Z][a-z]?)(\d*)/g)) n[s] = (n[s] || 0) + (k ? +k : 1); return n; };
  const PRUNE = 1e-9, MAXOFF = 40;
  function conv(a, b) {                                    // a, b: Map(offset -> [probability, mass x probability])
    const out = new Map();
    for (const [oa, [pa, ma]] of a) for (const [ob, [pb, mb]] of b) {
      const o = oa + ob; if (o > MAXOFF) continue;
      const p = pa * pb; if (p < PRUNE) continue;
      const cur = out.get(o) || [0, 0];
      cur[0] += p; cur[1] += ma * pb + mb * pa;            // mean mass of the group adds up: E[ma+mb]
      out.set(o, cur);
    }
    return out;
  }
  function elementDist(s) {
    const e = EL[s]; if (!e || !e.iso.length) throw new Error(I18N.t("tbl.iso.unavailable", { s }));
    const main = e.iso.reduce((a, b) => (b[2] > a[2] ? b : a)), d = new Map();
    for (const [A, m, pct] of e.iso) { const p = pct / 100; if (m == null || p <= 0) continue; const o = A - main[0]; d.set(o, [p, m * p]); }
    // keep only non-negative offsets relative to the lightest isotope: shift so the lightest is 0
    const o0 = Math.min(...d.keys()), out = new Map(); for (const [o, v] of d) out.set(o - o0, v); return out;
  }
  function power(d, n) {
    let res = new Map([[0, [1, 0]]]), base = d;
    while (n > 0) { if (n & 1) res = conv(res, base); n >>= 1; if (n) base = conv(base, base); }
    return res;
  }
  // pattern of an ion: element counts (already including the adduct) and charge z -> [{off, mz, rel}] (rel: % of the highest)
  function isoPattern(n, z = 1) {
    let dist = new Map([[0, [1, 0]]]);
    for (const [s, k] of Object.entries(n)) if (k > 0) dist = conv(dist, power(elementDist(s), k));
    const rows = [...dist].map(([o, [p, mp]]) => ({ off: o, p, mz: (mp / p - z * ELECTRON) / Math.abs(z) }));
    const top = Math.max(...rows.map(r => r.p));
    return rows.map(r => ({ off: r.off, mz: r.mz, rel: 100 * r.p / top })).filter(r => r.rel >= 0.05).sort((a, b) => a.mz - b.mz);
  }
  // neutral formula (Hill, no parentheses) + adduct name -> element counts of the ion and its charge
  function ionCounts(formula, adName) {
    const a = ADD.find(x => x.n === adName) || ADD[0], n = {}, M = counts(formula);
    for (const [s, k] of Object.entries(M)) n[s] = k * a.k;
    if (a.add) for (const [s, k] of Object.entries(counts(a.add))) n[s] = (n[s] || 0) + k;
    if (a.sub) for (const [s, k] of Object.entries(counts(a.sub))) n[s] = (n[s] || 0) - k;
    if (Object.values(n).some(k => k < 0)) throw new Error(I18N.t("tbl.iso.adductTooMany"));
    return { n, z: a.z, ad: a.n };
  }
  // ---------------------------------------------------------------- dialog #refdlg: one content at a time (Tavola periodica; Addotti and Perdite neutre outside the Dati view), titled with its name, no tab bar
  const TABS = [["pt", I18N.t("icon.pt"), periodic, bindPeriodic], ["ad", I18N.t("icon.adduct"), adductTab, bindAdducts], ["ls", I18N.t("icon.nl"), lossTab, bindLoss]];
  function open(which, opt = {}) {
    const d = Qs("#refdlg"), body = Qs("#refbody");
    if (which === "ls") { if (!d.open) lossPolStart(); if (opt.q != null) NL.q = String(opt.q); }
    const show = id => {
      const t = TABS.find(x => x[0] === id); if (!t) return; body.innerHTML = t[2](); if (t[3]) t[3](body, show);
      Qs("#reftitle").textContent = t[1];
    };
    Qs("#refx").onclick = () => d.close();
    show(which); if (!d.open) d.showModal();
    if (which === "ls" && opt.q != null) setTimeout(() => { const i = body.querySelector("#nl-q"); if (i) { i.focus(); i.select(); } }, 50);
  }
  function mountLosses(container, opt = {}) {
    lossPolStart();
    if (opt.q != null) NL.q = String(opt.q);
    container.innerHTML = lossTab();
    bindLoss(container, id => {
      if (id === "pt" || id === "ad") {
        if (window.BARRA && BARRA.isDataView()) {
          BARRA.setTab(id === "pt" ? "ptable" : "adducts");
        } else {
          open(id);
        }
      }
    });
    if (opt.q != null) {
      setTimeout(() => { const i = container.querySelector("#nl-q"); if (i) { i.focus(); i.select(); } }, 50);
    }
  }

  function mountAdducts(container) {
    container.innerHTML = adductTab();
    bindAdducts(container);
  }

  function setLossQuery(q) {
    NL.q = String(q || "");
    const qInp = document.querySelector("#nl-q");
    if (qInp) {
      qInp.value = NL.q;
      qInp.dispatchEvent(new Event("input", { bubbles: true }));
      setTimeout(() => { qInp.focus(); qInp.select(); }, 50);
    }
  }

  window.QQQRef = {
    open, massOf, mono, isoPattern, ionCounts, ADD, adductDiffs: calcAdductDiffs,
    mountLosses, mountAdducts, setLossQuery, periodic, bindPeriodic, adductTab, bindAdducts, lossTab, bindLoss
  };
})();
